// Throwaway harness: drives the real app.js submit handler under a minimal
// DOM stub so the login return shape can be checked without a browser.
let submitHandler;
const values = { username: "alice", password: "secret" };

global.document = {
  getElementById(id) {
    if (id === "login-form") {
      return {
        addEventListener(event, fn) {
          if (event === "submit") submitHandler = fn;
        },
      };
    }
    return { value: values[id] };
  },
};

